export function unifiedKnowledgeGraphSynthesis(agentOutputs) {
  const weightedVotes = agentOutputs.map(output => ({
    entity: output.entity,
    confidence: output.confidence
  }));

  const synthesizedGraph = weightedVotes.reduce((graph, vote) => {
    if (!graph[vote.entity]) {
      graph[vote.entity] = vote.confidence;
    } else {
      graph[vote.entity] = (graph[vote.entity] + vote.confidence) / 2;
    }
    return graph;
  }, {});

  return synthesizedGraph;
}